"""ChipBench 1.6 — AI / Git removed, project → collections, immersive fullscreen, soft / flat, per-project index cache,
recent robustness, HTML full mode, worker indexing of large notes.   python tests/t_v16.py"""
import asyncio, json
from util import *; from base_fs import *
R = {}; fails = []
def chk(name, cond, info=None):
    R[name] = bool(cond); print(('  ok  ' if cond else 'FAIL ') + name, '' if cond else (info if info is not None else ''))
    if not cond: fails.append(name)
async def main():
    with Server() as srv:
        async with async_playwright() as p:
            fs = base_fs(); fs['D:\\U2BX'] = {'dir': 1}; fs['C:\\Work\\page.html'] = {'t': '<html><body><h1>hello</h1></body></html>'}
            fs['C:\\Work\\big.md'] = {'t': '# 大笔记\n\n' + ''.join('## 节 %d\n\nRSCFD 寄存器 说明 %d 0x%04X\n\n- [ ] 待办 %d\n\n' % (i, i, i, i) for i in range(2500))}
            b, ctx, pg, errs = await launch(p, srv, fs, w=1440, h=900); ev = pg.evaluate
            async def wait(ms=300): await pg.wait_for_timeout(ms)
            chk('version 1.6.0', await ev("ChipBench.VERSION==='1.6.0'"))
            chk('no built-in AI', await ev("![...ChipBench.commands.keys()].some(k=>k.startsWith('ai.')) && !document.querySelector('#rail [data-x=ai], #crumbs [data-act=ai]') && !ChipBench.ai && !(ChipBench.right.tabs.ai || ChipBench.right.tabs.ailog)"))
            chk('no Git', await ev("!ChipBench.panels.git && !document.querySelector('#pane-git') && ![...ChipBench.commands.keys()].some(k=>k.startsWith('git.'))"))
            chk('MCP info kept', await ev("ChipBench.commands.has('mcp.info')"))
            chk('panel 项目 opens on 集合', await ev("ChipBench.panels.workspace.title==='项目' && document.querySelector('#ws-views button.on').dataset.v==='collections'"))
            chk('empty project explains collections + add-folder button', 'CAN IP' in await ev("document.querySelector('#ws-body').innerText") and await ev("!!document.querySelector('#ws-body [data-a=add-root]')"))
            await ev("ChipBench.ws.addRootPath('C:\\\\Work')"); await wait(1500)
            await ev("window.__pickFolder='D:\\\\U2BX'; void ChipBench.run('ws.new')"); await wait(300)
            await ev("document.querySelector('.modal [data-pick]').click()"); await wait(300)
            await ev("document.querySelector('#wsn-name').value='U2BX'; document.querySelector('#wsn-colls').value='CAN IP，时钟'; [...document.querySelectorAll('.modal button')].find(b=>b.textContent==='创建').click()"); await wait(1500)
            chk('new project with collections', await ev("ChipBench.ws.cur.name") == 'U2BX' and await ev("ChipBench.ws.cur.collections.map(c=>c.name)") == ['CAN IP', '时钟'])
            await ev("ChipBench.prompt=async()=>'RS-CANFD 接收流程'; document.querySelector('#ws-body .ws-row.grp [data-a=coll-new-doc]').click()"); await wait(1200)
            chk('new document in collection', await ev("ChipBench.app.current() && ChipBench.app.current().path") == 'D:\\U2BX\\集合\\CAN IP\\RS-CANFD 接收流程.md')
            await ev("ChipBench.openPath('C:\\\\Work\\\\DFA培训\\\\讲稿.md')"); await wait(800)
            await ev("document.querySelectorAll('#ws-body .ws-row.grp')[1].querySelector('[data-a=coll-add]').click()"); await wait(300)
            await ev("[...document.querySelectorAll('.menu-pop .mi')].find(m=>m.textContent.includes('当前文档')).click()"); await wait(800)
            chk('add current note to collection', await ev("ChipBench.ws.cur.collections[1].children.some(n=>ChipBench.W.label(n).includes('讲稿'))"))
            id2 = await ev("ChipBench.ws.cur.id"); id1 = await ev("(async()=>(await ChipBench.ws.list()).find(w=>w.id!=='" + id2 + "').id)()")
            await ev(f"ChipBench.ws.switchTo('{id1}')"); await pg.wait_for_function("ChipBench.index.status.state!=='building'", timeout=20000); await wait(1500)
            n1 = await ev("ChipBench.index.docs.size")
            await ev(f"ChipBench.ws.switchTo('{id2}')"); await wait(1500); await ev("window.__calls.length=0")
            t = await ev(f"(async()=>{{const t0=performance.now(); await ChipBench.ws.switchTo('{id1}'); return performance.now()-t0}})()"); await wait(1500)
            chk('switch back reuses cached index (no re-read)', await ev("window.__calls.filter(c=>c==='read_many').length") == 0 and await ev("ChipBench.index.docs.size") == n1)
            chk('switch is fast', t < 400, t)
            chk('large note indexed in worker (tasks + search)', await ev("(()=>{const d=ChipBench.index.docs.get(ChipBench.U.pkey('C:\\\\Work\\\\big.md')); return !!d && d.tasks.length===2500})()") and len(await ev("ChipBench.index.runSearch('RSCFD')")) > 0)
            await ev("ChipBench.openPath('C:\\\\Work\\\\big.md')"); await wait(1200)
            await ev("window.__lt=[]; new PerformanceObserver(l=>l.getEntries().forEach(e=>window.__lt.push(e.duration))).observe({entryTypes:['longtask']})")
            await ev("ChipBench.app.ed.insert('x')"); await wait(800); await ev("window.__lt.length=0; ChipBench.app.save()"); await wait(3000)
            chk('saving a large note causes no long task', await ev("window.__lt.filter(x=>x>50).length") == 0, await ev("window.__lt"))
            await ev("ChipBench.openPath('C:\\\\Work\\\\page.html')"); await wait(800)
            await ev("ChipBench.W.markOpened(ChipBench.ws.cur,'C:\\\\Work\\\\gone.md'); ChipBench.ws.view='recent'; ChipBench.ws.draw()"); await wait(300)
            await ev("ChipBench.confirm=async()=>true"); await pg.click("#ws-body .ws-row[data-path$='gone.md']"); await wait(600)
            chk('recent: missing file removed', await ev("!ChipBench.ws.cur.recent.some(r=>r.path.endsWith('gone.md'))"))
            await pg.click("#ws-body .ws-row[data-path$='page.html']"); await wait(800)
            chk('recent: HTML opens', await ev("ChipBench.app.current().name") == 'page.html')
            await ev("[...document.querySelectorAll('.view-host:not(.hide) .view-tools button')].find(b=>b.textContent.includes('完整功能')).click()"); await wait(300)
            chk('HTML full mode → separate window', 'page.html' in (await ev("window.__web||''")))
            await ev("ChipBench.openPath('C:\\\\Work\\\\DFA培训\\\\讲稿.md')"); await wait(600)
            await pg.keyboard.press('F11'); await wait(500)
            vis = await ev("['rail','side','status','tabs','crumbs'].map(id=>{const el=document.getElementById(id),r=el.getBoundingClientRect(),cs=getComputedStyle(el); return cs.display==='none'||r.width===0||cs.opacity==='0'||r.bottom<=0})")
            chk('F11 hides all bars', all(vis), vis)
            chk('F11 document fills window', await ev("(()=>{const r=document.getElementById('main').getBoundingClientRect(); return r.left<=1 && r.top<=1 && r.width>=innerWidth-2})()"))
            await pg.mouse.move(700, 2); await wait(500)
            chk('top edge reveals bars', await ev("document.body.classList.contains('bars')"))
            await pg.mouse.move(700, 500); await wait(900)
            chk('bars hide again', not await ev("document.body.classList.contains('bars')"))
            await pg.keyboard.press('Escape'); await wait(400)
            chk('Esc leaves fullscreen', await ev("!document.body.classList.contains('immersive')"))
            chk('soft interface default', await ev("document.documentElement.dataset.fx==='soft' && getComputedStyle(document.getElementById('main')).borderTopLeftRadius!=='0px'"))
            await ev("ChipBench.run('prefs')"); await wait(400)
            await ev("(()=>{const s=document.querySelector('.modal [data-fx]'); s.value='flat'; s.dispatchEvent(new Event('change'))})()"); await wait(200)
            chk('flat switch', await ev("document.documentElement.dataset.fx==='flat' && getComputedStyle(document.getElementById('main')).borderTopLeftRadius==='0px'"))
            await pg.keyboard.press('Escape')
            chk('logo = app icon', await ev("getComputedStyle(document.querySelector('#rail .logo')).backgroundImage.includes('logo.png')"))
            chk('no page errors', not [e for e in errs if 'pageerror' in e], errs[:5])
            await b.close()
    print(json.dumps({'passed': sum(R.values()), 'total': len(R), 'fails': fails}, ensure_ascii=False))
asyncio.run(main())
import sys as _sys; _sys.exit(1 if fails else 0)
